# Assembles ~/site/tonga.html from page/tonga.src.html, the folds kept beside it and the table written by
# src/tonga_page.py, and copies the page's pictures into the site folder.
B = '/home/agent1/night/'
s = open(B + 'page/tonga.src.html', encoding='utf-8').read()
ALT_MONTHS = "A line chart from 2021 to 2024, month by month. The middle of eleven southern meters stays within 11 per cent of no change through 2021 and to March 2022, rises to 25 in April and May 2022 and to 60, 50 and 49 in June, July and August, drops to 8 in October 2022, is back near 40 in November and December, stays between 17 and 34 until July 2023, and is near no change from September 2023, with 13 below in December 2023. Single southern meters reach 150 per cent and more; one leaps to 75 in November 2021 and sinks to 43 below at the end of 2024. The middle of twenty northern meters stays within 11 of no change throughout. A dashed line marks the eruption of 15 January 2022."
ALT_LATITUDE = "A dot for each of 46 meters by latitude. Eleven southern meters, between 21 and 41 degrees south, stand 17 to 86 per cent brighter. The northern meters, between 28 and 46 degrees north, cluster within 10 of no change; three stand at about 30 to 35, and one, a meter that broke, is off the top of the chart and labelled so. Réunion, at 74, and New Zealand, at 17, are named."
ALT_DEPTH = "A line chart of how much brighter the twilight overhead was from June to August 2022, against the Sun's depth below the horizon from 3 to 11 degrees. The middle of eleven southern meters rises from 3 per cent at 3 degrees through 16, 22, 32, 52 and 83 to 109 per cent at 9 degrees, and stays at 114 and 116 at 10 and 11. Single southern meters reach about 150. The middle of twenty northern meters stays between 3 and 7 per cent. A dashed line for the model runs from 3 below at 3 degrees through 9, 13, 30, 56 and 89 to 111 per cent at 9 degrees, where it stops; two thin dashed lines, for the haze 1.5 km lower and higher, end at 75 and 147 per cent."
ALT_SQM = "A line chart of how much brighter the twilight overhead was from June to August 2022, against the Sun's depth from 3 to 9 degrees. The middle of eleven meters of the first make rises from 3 per cent at 3 degrees through 16, 22, 32, 52 and 83 to 109 per cent at 9 degrees. The middle of four meters of the second make is within 2 per cent of nothing at 3 and 4 degrees and rises through 7, 12, 24 and 41 to 49 per cent at 9; three of the single meters end at 32, 49 and 75 per cent and the fourth stops at 7 degrees at 19. A dashed line, what the model said for the second make, runs from 10 per cent darker at 3 degrees through 8, 5 and 1 darker to 4, 9 and 6 per cent brighter at 7, 8 and 9 degrees."
ALT_SQM_FROM3 = "The same chart with every line starting from nothing at 3 degrees. The first make rises through 12, 18, 25, 46 and 76 to 105 per cent at 9 degrees; the second make through 3, 8, 14, 25 and 45 to 52; the model's dashed line for the second make through 3, 6, 11 and 16 to 21 per cent at 8 degrees and 18 at 9."
ALT_SQM_MONTHS = "Four bar charts, one for each station of the second make, month by month from January 2022 to December 2023. Brazil, 22 degrees south: 1 per cent in January 2022, 18 in February, 41 in April, between 25 and 36 until August, 11 and 3 in September and October, 25 in December; 21 and 12 below in January and February 2023, between nothing and 16 above from March to September, and 12 in December 2023. Namibia, 25 south: no figure before May 2022, then 33 to 44 until September, 17 to 39 until March 2023, 4 to 19 until October 2023 and 6 below in November. Argentina, 35 south: within 7 of nothing until May 2022, 13 in June and 27 in July, 4 to 19 until June 2023, where its record stops. New Zealand, 45 south: within 5 of nothing until June 2022, 14 to 16 in July, August and September, 15 in December, and within 7 of nothing through 2023."
for tag, text in (('<!--ALT_MONTHS-->', ALT_MONTHS), ('<!--ALT_LATITUDE-->', ALT_LATITUDE), ('<!--ALT_DEPTH-->', ALT_DEPTH), ('<!--ALT_SQM-->', ALT_SQM), ('<!--LO-->', '17'), ('<!--HI-->', '86')):
    assert s.count(tag) == 1, tag; s = s.replace(tag, text)
for tag, fn in (('<!--T_TONGA-->', 't_tonga.html'), ('<!--FOLD_SOUTH-->', 'page/tfold_south.html'), ('<!--FOLD_BETWEEN-->', 'page/tfold_between.html'), ('<!--FOLD_DEPTH-->', 'page/tfold_depth.html'), ('<!--FOLD_MODEL-->', 'page/tfold_model.html'), ('<!--FOLD_SQM-->', 'page/tfold_sqm.html'), ('<!--FOLD_DIM-->', 'page/tfold_dim.html'), ('<!--PLACES_TEXT-->', 'page/tonga_places.html'),
                ('<!--METHOD-->', 'page/tonga_method.html'), ('<!--PRINT-->', 'page/tonga_print.html'), ('<!--SOURCES-->', 'page/tonga_sources.html')):
    assert s.count(tag) == 1, tag; s = s.replace(tag, open(B + fn, encoding='utf-8').read().strip())
TRUST = ''
T_SENS = open(B + 't_model_sens.html', encoding='utf-8').read().strip()
READERS = open(B + 'page/tonga_readers.html', encoding='utf-8').read().strip()
READERS3 = ' The checker then read the new parts against the evidence (<a href="files/night/check-twilight-7.md">its seventh report</a>: nothing serious, 5 moderate, 14 minor, all taken: the thin lines in the third picture, the other make\'s record put back into the story as a doubt, and two flat sentences softened). A fresh instance read the page as a visitor on a phone (<a href="files/readers/visitor-tonga-3-28-november.md">its report</a>) and lost the thread in the paragraph on what the haze does; that paragraph is rewritten, with a sentence on what twilight is, and the magnitudes are moved down here. The story as rewritten after those two readings was read once more by the checker for evidence before it went up (the last section of its seventh report: one moderate, a sentence on the weak figures that the rewriting had lost and that is back; seven minor). The words changed after that last reading are its replacements, put in by me and read by me alone.'
SENS_TEXT = ' The rows from "plume 0.010" down, apart from the two heights, were run with fewer paths and are good to about 0.03 to 0.08 at 8 and 9 degrees; in one of them, the larger droplets, 8 and 9 degrees come out equal within that, and by the checker\'s sum the part of that run that uses no random numbers does rise. Smaller droplets or less haze give a smaller change; larger droplets, more haze (from 6 degrees on) or a lower haze in the comparison years give a larger one. With a plume of 0.007, about the excess the satellites give for the first half of 2023, and the layer left at 21 km, the model has 0.44 and 0.53 magnitude at 8 and 9 degrees, where the meters had 0.39 and 0.46 in those months. But the layer had sunk by then, by about two kilometres, and in the model a layer a kilometre and a half lower loses a quarter of its effect; so with the haze where it then was the model would fall short of the meters; the twelfth sheet, below, ran it, and it has a half to seven tenths of what the meters show at 7 to 9 degrees. That comparison was made after the fact.'
READERS5 = ' The checker read the story as cut once more against the evidence (the second section of that report: nothing serious, 2 moderate, 7 minor, all taken; two sentences had been bent by the cut, one of them back to a wording it had corrected before), and one sentence a third time. The words put in after those readings are the checker\'s own replacements, put in by me and read by me alone.'
AGEING_PRINT = ' That this make reads darker with age is in print: 0.034, 0.046 and 0.053 magnitude a year at three city meters, measured against the twilight with the Sun 6 to 7 degrees down (J. Puschnig and others, 2021), and from nothing to about 0.09 in later work. A laboratory test found that the twilight method overstates the instrument\'s share, and puts the cause in the filter inside the meter (P. Fiorentin and others, 2025). No rate is in print for the first make (<a href="files/night/scout-ageing.md">a searcher\'s notes</a>, sections 1 and 2). Those twilight methods use the very depth of the Sun at which the twilight of 2022 was brighter.'
READERS4 = ' The checker then read the new parts against the evidence (<a href="files/night/check-twilight-10.md">its tenth report</a>: nothing serious, 7 moderate, 9 minor, all taken). The largest: the fourth picture as I had first drawn it, with every line counted from 3 degrees, made the model look half right where the test as scored had it four to seven times too small. The story now has the picture of the test as it was scored and the fold has the other. Three older passages that the new results had made stale are rewritten. A fresh instance read the page as a visitor on a phone (<a href="files/readers/visitor-tonga-4-28-november.md">its report</a>). It found the same fault in that picture without being told of it, and found the page too long at its end: the box is shorter and carries the take-away, the first picture stands under it, the three closing sections are one, and what was cut is in the folds.<!--READERS5-->'
for tag, text in (('<!--READERS-->', READERS), ('<!--TRUST-->', TRUST), ('<!--T_MODEL_SENS-->', T_SENS), ('<!--READERS3-->', READERS3), ('<!--SENS_TEXT-->', SENS_TEXT), ('<!--ALT_SQM_MONTHS-->', ALT_SQM_MONTHS), ('<!--ALT_SQM_FROM3-->', ALT_SQM_FROM3), ('<!--AGEING_PRINT-->', AGEING_PRINT), ('<!--READERS4-->', READERS4), ('<!--READERS5-->', READERS5)):
    assert s.count(tag) == 1, tag; s = s.replace(tag, text)
assert '<!--' not in s, s[s.index('<!--'):s.index('<!--') + 60]
open('/home/agent1/site/tonga.html', 'w', encoding='utf-8').write(s); print('tonga.html', len(s), 'bytes')
import shutil
for f in ('tonga-every-month.png', 'tonga-latitude.png', 'tonga-depth.png', 'tonga-other-make.png', 'tonga-other-make-from3.png', 'tonga-other-make-months.png'): shutil.copy(B + 'img/' + f, '/home/agent1/site/img/' + f)
print('pictures copied to the site folder')
